<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { invoke } from '@tauri-apps/api/core';
import { Award, CalendarDays, CheckCircle2, FileBadge, FileText, LoaderCircle, MapPin, Sparkles, GraduationCap } from 'lucide-vue-next';
import { rows } from '../db';
import { notify, selectedStudent } from '../store';
import type { School } from '../types';
const school=ref<School|null>(null);const activityCount=ref(0);const gradeCount=ref(0);const generating=ref(false);
const initial=computed(()=>selectedStudent.value?.name.split(' ').map(v=>v[0]).slice(0,2).join('')??'–');
watch(()=>selectedStudent.value?.student_id,async id=>{school.value=null;activityCount.value=0;gradeCount.value=0;if(!id)return;const [s,a,g]=await Promise.all([rows<School>('SELECT * FROM schools WHERE school_id=$1',[selectedStudent.value?.school_id]),rows<{total:number}>('SELECT COUNT(*) AS total FROM student_additional_mint_activities WHERE student_id=$1',[id]),rows<Record<string,unknown>>('SELECT * FROM students WHERE student_id=$1',[id])]);school.value=s[0]??null;activityCount.value=Number(a[0]?.total??0);const row=g[0];gradeCount.value=row?Array.from({length:5},(_,i)=>Array.from({length:4},(_,j)=>row[`grade_${i+1}_${j+1}`]).filter(v=>v!==null&&v!==undefined&&v!=='').length).reduce((x,y)=>x+y,0):0;},{immediate:true});
async function generate(){if(!selectedStudent.value)return;generating.value=true;try{const result=await invoke<boolean>('generate_pdf');if(result)notify('Das Zertifikat wurde erfolgreich als PDF gespeichert.');}catch(e){notify(`PDF-Generierung fehlgeschlagen: ${String(e)}`,'error');}finally{generating.value=false;}}
</script>

<template>
 <div v-if="!selectedStudent" class="notice-card"><span class="notice-icon"><FileBadge :size="20"/></span><div><b>Wähle zuerst eine:n Schüler:in</b><p>Das Zertifikat wird mit den Daten und der Schule dieser Person erstellt.</p></div><button class="button primary" @click="$router.push('/students')">Schüler:innen öffnen</button></div>
 <template v-else><div class="export-layout"><section class="panel certificate-preview"><header class="panel-heading"><div><h2>Zertifikatsübersicht</h2><p>Die bestehenden Angaben werden in das MINT-EC PDF übernommen.</p></div><span class="preview-tag"><Sparkles :size="14"/>VORSCHAU</span></header><div class="certificate-sheet"><div class="cert-topline"><span class="cert-logo"><Sparkles :size="20"/></span><span>MINT-EC<br/><small>ZERTIFIKAT</small></span></div><div class="cert-rule"></div><p class="cert-eyebrow">ZERTIFIKAT FÜR BESONDERE LEISTUNGEN</p><h2>{{selectedStudent.name}}</h2><p class="cert-description">MINT-EC Zertifikat · Abitur {{selectedStudent.graduation_year??'—'}}</p><div class="cert-fields"><div><span><GraduationCap :size="14"/>Schule</span><b>{{school?.school_name??selectedStudent.school_name??'—'}}</b></div><div><span><MapPin :size="14"/>Ort</span><b>{{school?.school_location||'—'}}</b></div><div><span><CalendarDays :size="14"/>Geburtsdatum</span><b>{{selectedStudent.birthday?new Date(selectedStudent.birthday+'T00:00:00').toLocaleDateString('de-DE'):'—'}}</b></div></div><div class="cert-pillars"><div><b>I</b><span>Fachliche Kompetenz</span><small>{{gradeCount}} von 20 Noten erfasst</small></div><div><b>II</b><span>Wissenschaftliches Arbeiten</span><small>Angaben werden übernommen</small></div><div><b>III</b><span>MINT-Aktivitäten</span><small>{{activityCount}} erreichte Stufen</small></div></div><div class="cert-signatures"><span>{{school?.school_functionary_1||'Unterschrift 1'}}</span><span>{{school?.school_functionary_2||'Unterschrift 2'}}</span></div></div></section><aside class="export-aside"><section class="panel export-ready"><span class="ready-icon"><CheckCircle2 :size="20"/></span><h2>Bereit zum Export</h2><p>Der Rust PDF-Generator erstellt das Zertifikat und öffnet den Dialog zum Speichern.</p><div class="ready-meta"><span>Schüler:in</span><b>{{selectedStudent.name}}</b><span>Aktivitäten</span><b>{{activityCount}} erfasst</b><span>Noten</span><b>{{gradeCount}} von 20</b></div><button class="button primary export-button" :disabled="generating" @click="generate"><LoaderCircle v-if="generating" class="spin" :size="17"/><FileBadge v-else :size="17"/>{{generating?'PDF wird erstellt…':'PDF erstellen'}}</button></section><div class="info-callout"><FileText :size="17"/><span>Der Speicherort kann im anschließenden Dialog gewählt werden. Der zuletzt genutzte Ordner bleibt in den Einstellungen hinterlegt.</span></div></aside></div></template>
</template>
